insert into public.stilnytsi_materials (slug, data, hidden, position) values ('vratza-r1', '{"slug":"vratza-r1","name":"Вапняк Vratza R1","material":"marmur","family":"Вапняк","origin":"Болгарія","tone":"світло-бежевий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["фасади","підлога","облицювання"],"description":"Вапняк Vratza R1 — світло-бежевий болгарський камінь із дрібним рівним зерном, найближчий за виглядом до єрусалимського вапняку, але з європейського складу. Фасади, підлоги, облицювання стін; матовий і шліфований фініш.","image":"/materials/vratza-r1.webp","cardImage":"/materials/vratza-r1.webp","care":"Нейтральний pH, просочення та негайне видалення кислот.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":95,"unit":"м²","currency":"€"},"specs":{"density":"2500","absorption":"2,0","compressive":"70","frost":"50","radiation":"I клас"}}'::jsonb, true, 1100) on conflict (slug) do nothing;
insert into public.stilnytsi_materials (slug, data, hidden, position) values ('vratza-r3', '{"slug":"vratza-r3","name":"Вапняк Vratza R3","material":"marmur","family":"Вапняк","origin":"Болгарія","tone":"бежевий із мушлями","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["фасади","тераси","облицювання"],"description":"Вапняк Vratza R3 — бежевий болгарський вапняк із помітними мушлями й порами, тепліший і фактурніший за R1. Фасади, тераси, огорожі; після просочення тримає вологу й мороз.","image":"/materials/vratza-r3.webp","cardImage":"/materials/vratza-r3.webp","care":"Нейтральний pH, просочення та негайне видалення кислот.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":52,"unit":"м²","currency":"€"},"specs":{"density":"2450","absorption":"2,5","compressive":"60","frost":"50","radiation":"I клас"}}'::jsonb, true, 1101) on conflict (slug) do nothing;
insert into public.stilnytsi_materials (slug, data, hidden, position) values ('travertino-medium', '{"slug":"travertino-medium","name":"Травертин Medium","material":"marmur","family":"Травертин","origin":"Туреччина","tone":"бежевий середнього тону","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["фасади","підлога","ванна"],"description":"Травертин Medium — бежевий турецький камінь середнього тону з дрібними порами, класична заміна італійського Classico. Фасади, підлоги, ванні кімнати з заповненими порами.","image":"/materials/travertino-medium.webp","cardImage":"/materials/travertino-medium.webp","care":"Нейтральний pH, просочення та негайне видалення кислот.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":95,"unit":"м²","currency":"€"},"specs":{"density":"2450","absorption":"1,5","compressive":"70","frost":"50","radiation":"I клас"}}'::jsonb, true, 1102) on conflict (slug) do nothing;
insert into public.stilnytsi_materials (slug, data, hidden, position) values ('travertino-alabastrino', '{"slug":"travertino-alabastrino","name":"Травертин Alabastrino","material":"marmur","family":"Травертин","origin":"Італія","tone":"світлий кремовий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["облицювання","підлога","ванна"],"description":"Травертин Alabastrino — світлий кремовий італійський камінь із тонким рівним шаруванням і майже без великих пор. Найсвітліший із травертинів: підлоги, стіни ванних, підвіконня.","image":"/materials/travertino-alabastrino.webp","cardImage":"/materials/travertino-alabastrino.webp","care":"Нейтральний pH, просочення та негайне видалення кислот.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":270,"unit":"м²","currency":"€"},"specs":{"density":"2500","absorption":"1,2","compressive":"80","frost":"50","radiation":"I клас"}}'::jsonb, true, 1103) on conflict (slug) do nothing;
insert into public.stilnytsi_materials (slug, data, hidden, position) values ('travertino-safari-brown', '{"slug":"travertino-safari-brown","name":"Травертин Safari Brown","material":"marmur","family":"Травертин","origin":"Туреччина","tone":"коричневий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["фасади","каміни","підлога"],"description":"Травертин Safari Brown — коричневий турецький камінь із теплими смугами від горіхового до пісочного. Каміни, фасадні акценти, підлоги в темних інтер’єрах.","image":"/materials/travertino-safari-brown.webp","cardImage":"/materials/travertino-safari-brown.webp","care":"Нейтральний pH, просочення та негайне видалення кислот.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":160,"unit":"м²","currency":"€"},"specs":{"density":"2450","absorption":"1,5","compressive":"70","frost":"50","radiation":"I клас"}}'::jsonb, true, 1104) on conflict (slug) do nothing;
insert into public.stilnytsi_materials (slug, data, hidden, position) values ('le-blanc', '{"slug":"le-blanc","name":"Кварцит Le Blanc","material":"kvarcyt","family":"Кварцит","origin":"Бразилія","tone":"білий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","острови","ванна"],"description":"Кварцит Le Blanc — білий бразильський камінь із ледь помітними сірими хмарками, найчистіший білий серед кварцитів. Твердий і стійкий до кислот: світлі кухні, острови, ванні.","image":"/materials/le-blanc.webp","cardImage":"/materials/le-blanc.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"specs":{"density":"2650","absorption":"0,20","compressive":"230","frost":"100","radiation":"I клас"}}'::jsonb, true, 1105) on conflict (slug) do nothing;
