insert into public.stilnytsi_materials (slug, data, hidden, position) values ('macaubas-fantasy', '{"slug":"macaubas-fantasy","name":"Кварцит Macaubas Fantasy","material":"kvarcyt","family":"Кварцит","origin":"Бразилія","tone":"сіро-білий у хвилястих смугах","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","панно"],"description":"Кварцит Macaubas Fantasy — сіро-білий камінь із хвилястими смугами, як у White Macaubas, але з рухливішим рисунком. Стільниці, панно й острови, де потрібен виразний природний малюнок.","image":"/materials/macaubas-fantasy.webp","cardImage":"/materials/macaubas-fantasy.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"specs":{"density":"2650","absorption":"0,25","compressive":"200","frost":"100","radiation":"I клас"}}'::jsonb, true, 1107) on conflict (slug) do nothing;
insert into public.stilnytsi_materials (slug, data, hidden, position) values ('white-pearl', '{"slug":"white-pearl","name":"Кварцит White Pearl","material":"kvarcyt","family":"Кварцит","origin":"Бразилія","tone":"перлинно-білий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","ванна"],"description":"Кварцит White Pearl — перлинно-білий бразильський камінь із дрібним блиском кристалів і ніжними сірими лініями. Стільниці й ванні, добре тримає полірування.","image":"/materials/white-pearl.webp","cardImage":"/materials/white-pearl.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"specs":{"density":"2650","absorption":"0,20","compressive":"220","frost":"100","radiation":"I клас"}}'::jsonb, true, 1108) on conflict (slug) do nothing;
