insert into public.stilnytsi_materials (slug, data, hidden, position) values ('honey-onyx', '{"slug":"honey-onyx","name":"Онікс Honey","material":"marmur","family":"Онікс","origin":"Імпорт","tone":"медово-жовтий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["панно","стійки","підсвітка"],"description":"Онікс Honey — медово-жовтий напівпрозорий камінь із шарами від золотистого до світло-коричневого. Підсвічені стійки, панно, ніші; імпортний сляб під замовлення.","image":"/materials/honey-onyx.webp","cardImage":"/materials/honey-onyx.webp","care":"Нейтральний pH, просочення та негайне видалення кислот.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":700,"unit":"м²","currency":"€"},"specs":{"density":"2650","absorption":"0,20","compressive":"80","frost":"25","radiation":"I клас"}}'::jsonb, true, 1113) on conflict (slug) do nothing;
insert into public.stilnytsi_materials (slug, data, hidden, position) values ('bianco-a-onyx', '{"slug":"bianco-a-onyx","name":"Онікс Bianco A","material":"marmur","family":"Онікс","origin":"Імпорт","tone":"білий напівпрозорий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["панно","ванна","підсвітка"],"description":"Онікс Bianco A — білий напівпрозорий камінь із м’якими сірими й кремовими хмарами. Найсвітліший онікс для панно, ванн і підсвічених стін; імпортний сляб під замовлення.","image":"/materials/bianco-a-onyx.webp","cardImage":"/materials/bianco-a-onyx.webp","care":"Нейтральний pH, просочення та негайне видалення кислот.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":685,"unit":"м²","currency":"€"},"specs":{"density":"2650","absorption":"0,20","compressive":"80","frost":"25","radiation":"I клас"}}'::jsonb, true, 1114) on conflict (slug) do nothing;
insert into public.stilnytsi_materials (slug, data, hidden, position) values ('caesarstone-4011-cloudburst-concrete', '{"slug":"caesarstone-4011-cloudburst-concrete","name":"Caesarstone 4011 Cloudburst Concrete","material":"kvarc","family":"Кварц","origin":"Caesarstone","tone":"сірий бетон","finishes":["полірований","матовий"],"thicknesses":[20,30],"applications":["стільниці","острови","підвіконня"],"description":"Caesarstone 4011 Cloudburst Concrete — кварцова поверхня під світлий бетон із ледь помітними хмарками й матовим фінішем. Сучасні кухні й ванні без блиску; не має пор, гаряче — через підставку.","image":"/materials/caesarstone-4011-cloudburst-concrete.webp","cardImage":"/materials/caesarstone-4011-cloudburst-concrete.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"specs":{"density":"2400","absorption":"≤ 0,05","compressive":"180","frost":"не для вулиці","radiation":"I клас"},"brand":"Caesarstone"}'::jsonb, true, 1115) on conflict (slug) do nothing;
insert into public.stilnytsi_materials (slug, data, hidden, position) values ('caesarstone-5143-white-attica', '{"slug":"caesarstone-5143-white-attica","name":"Caesarstone 5143 White Attica","material":"kvarc","family":"Кварц","origin":"Caesarstone","tone":"білий із сірими жилами","finishes":["полірований","матовий"],"thicknesses":[20,30],"applications":["стільниці","острови","підвіконня"],"description":"Caesarstone 5143 White Attica — білий кварц із сірими жилами в дусі мармуру Калаката. Світла кухня з характером мармуру без його чутливості до кислот.","image":"/materials/caesarstone-5143-white-attica.webp","cardImage":"/materials/caesarstone-5143-white-attica.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"specs":{"density":"2400","absorption":"≤ 0,05","compressive":"180","frost":"не для вулиці","radiation":"I клас"},"brand":"Caesarstone"}'::jsonb, true, 1116) on conflict (slug) do nothing;
insert into public.stilnytsi_materials (slug, data, hidden, position) values ('caesarstone-5100-vanilla-noir', '{"slug":"caesarstone-5100-vanilla-noir","name":"Caesarstone 5100 Vanilla Noir","material":"kvarc","family":"Кварц","origin":"Caesarstone","tone":"білий із чорними жилами","finishes":["полірований","матовий"],"thicknesses":[20,30],"applications":["стільниці","острови","підвіконня"],"description":"Caesarstone 5100 Vanilla Noir — білий кварц із тонкими чорними жилами, графічний і контрастний. Острови, стільниці, фартухи в чорно-білих кухнях.","image":"/materials/caesarstone-5100-vanilla-noir.webp","cardImage":"/materials/caesarstone-5100-vanilla-noir.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"specs":{"density":"2400","absorption":"≤ 0,05","compressive":"180","frost":"не для вулиці","radiation":"I клас"},"brand":"Caesarstone"}'::jsonb, true, 1117) on conflict (slug) do nothing;
insert into public.stilnytsi_materials (slug, data, hidden, position) values ('caesarstone-5810-black-tempal', '{"slug":"caesarstone-5810-black-tempal","name":"Caesarstone 5810 Black Tempal","material":"kvarc","family":"Кварц","origin":"Caesarstone","tone":"чорний зі світлими жилами","finishes":["полірований","матовий"],"thicknesses":[20,30],"applications":["стільниці","острови","підвіконня"],"description":"Caesarstone 5810 Black Tempal — чорний кварц зі світлими розводами, як у темного мармуру. Матовий фініш ховає відбитки; стільниці й острови в темних кухнях.","image":"/materials/caesarstone-5810-black-tempal.webp","cardImage":"/materials/caesarstone-5810-black-tempal.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"specs":{"density":"2400","absorption":"≤ 0,05","compressive":"180","frost":"не для вулиці","radiation":"I клас"},"brand":"Caesarstone"}'::jsonb, true, 1118) on conflict (slug) do nothing;
